const $=(selector: string): Dynamic=>document.querySelector(selector);
const money=(value: unknown)=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(Number(value)||0);
const entities: Record<string, string>={'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'};
const enc=(value: unknown)=>String(value??'').replace(/[&<>"']/g,(character: Dynamic)=>entities[character]??character);
const dt=(value: string | number | Date)=>new Date(value).toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'});
const formatSum=(value: unknown)=>`${money(value)} BYN`;
const errorMessage=(value: unknown)=>value instanceof Error?value.message:String(value);
